function initials(name:string){return name.split(' ').map(x=>x[0]).slice(0,2).join('');}
function Avatar({name,index=0}:{name:string;index?:number}){return <span className="avatar" style={index%3===1?{background:'#e8edfc',color:'#667ca9'}:index%3===2?{background:'#f3e5e5',color:'#9b7474'}:{}}>{initials(name)}</span>;}
