 {view==='prayer'&&<><div className="toolbar"><Tabs value={subtab} onValueChange={value=>{setSubtab(value);void refresh();}} className="tab-line"><TabsList>{['Requests','Members','Delivery history'].map(t=><TabsTrigger key={t} value={t} onClick={()=>{if(subtab===t)void refresh();}}>{t}</TabsTrigger>)}</TabsList></Tabs><a className="ml-auto" href={`${basePath}/prayer`} target="_blank" rel="noreferrer"><Button variant="outline"><ExternalLink size={15}/>Preview request form</Button></a></div>{subtab==='Requests'&&<PrayerAutomationTools state={state} busy={busy} run={run} onRefresh={refresh} linkedRequest={linkedRequest}/>}{subtab==='Members'&&<section className="panel"><div className="panel-head"><h2>{people.filter(p=>p.prayerMember).length} prayer-chain members</h2><Button size="sm" onClick={()=>setModal({type:'person'})}><UserPlus size={15}/>Add member</Button></div><Table><TableHeader><TableRow><TableHead>Member</TableHead><TableHead>Phone</TableHead><TableHead>Permission</TableHead><TableHead>Membership</TableHead></TableRow></TableHeader><TableBody>{people.filter(p=>p.prayerMember).map(p=><TableRow key={p.id}><TableCell><button className="font-semibold" onClick={()=>setSelected(p.id)}>{p.name}</button></TableCell><TableCell>{p.phone}</TableCell><TableCell><Badge tone={p.prayerSms?'teal':'amber'}>{p.prayerSms?'Recorded':'Not recorded'}</Badge></TableCell><TableCell><Button size="sm" variant="outline" disabled={busy} onClick={()=>run({type:'person.status',id:p.id,field:'prayerMember',value:false})}>Remove from chain</Button></TableCell></TableRow>)}</TableBody></Table><div className="p-5 text-sm muted">Adding someone here never adds them to a previously approved broadcast.</div></section>}{subtab==='Delivery history'&&<section className="panel"><div className="panel-head"><h2>Broadcast delivery queue</h2><Button size="sm" variant="outline" disabled={busy} onClick={()=>run({type:'delivery.check'})}><RefreshCw size={14}/>Check eligibility</Button></div>{state.deliveries.filter(d=>state.messages.find(m=>m.id===d.messageId)?.program==='prayer').length?<Table><TableHeader><TableRow><TableHead>Recipient</TableHead><TableHead>Status</TableHead><TableHead>Details</TableHead></TableRow></TableHeader><TableBody>{state.deliveries.filter(d=>state.messages.find(m=>m.id===d.messageId)?.program==='prayer').map(d=><TableRow key={d.id}><TableCell>{state.people.find(p=>p.id===d.target.personId)?.name}</TableCell><TableCell><Badge>{d.status}</Badge></TableCell><TableCell>{d.reason}</TableCell></TableRow>)}</TableBody></Table>:<Empty title="No broadcasts queued yet" detail="Approve a prayer draft to see its individual delivery records. Prayer line activity shows the sending queue."/>}</section>}</>}
