 {tab==='Workflow rules'&&<><div className="soft-banner mb-6"><SlidersHorizontal size={20} className="shrink-0"/><span>Set the timing and wording here. Saving a rule holds its existing unsent drafts for a fresh review. Approval and contact permissions always apply.</span></div><div className="space-y-4">{state.rules.map((r,i)=><section className="panel p-6 flex justify-between gap-4 items-center" key={r.id}><div className="flex gap-4"><span className="stat-icon !size-11 font-semibold">{String(i+1).padStart(2,'0')}</span><div><div className="flex items-center gap-3"><h3>{r.title}</h3><Badge tone={r.enabled?'teal':'gray'}>{r.enabled?'Enabled':'Paused'}</Badge></div><p className="text-sm muted mt-2">When a guest is at “{r.stage}”, wait {r.days} {r.days===1?'day':'days'}, then prepare {r.channel==='sms'?'a text':'an email'}. {recurrenceSummary(r.recurrence)}.</p><p className="text-xs muted mt-2">Version {r.version} · Always requires your approval</p></div></div><Button variant="outline" onClick={()=>openRule(r)}><PenLine size={15}/>Edit rule</Button></section>)}</div><section className="panel p-6 mt-6"><h3>Previous rule versions</h3>{state.ruleHistory.length?state.ruleHistory.slice(0,8).map(r=><div className="settings-row" key={r.id+r.version}><div><span className="text-sm">{r.title} · version {r.version}</span><p>{r.days}-day delay · {r.channel.toUpperCase()} · {recurrenceSummary(r.recurrence)}</p></div><Button variant="outline" size="sm" disabled={busy} onClick={()=>run({type:'rule.restore',id:r.id,version:r.version})}>Restore version</Button></div>):<p className="text-sm muted mt-2">Previous settings are saved here whenever you edit a rule.</p>}</section></>}
