 {tab==='Access & history'&&<><AdminPhoneTools key={state.settings.adminPhone} state={state} busy={busy} run={run}/><section className="panel p-6 mb-6"><div className="flex gap-4 items-start"><ShieldCheck size={26} className="text-teal-700"/><div><h2>Owner-only workspace</h2><p className="text-sm muted mt-2">Your account can manage records and approve drafts. Additional staff access and role assignment will be configured before a shared church rollout. Prayer members do not receive staff access.</p></div></div></section><section className="panel"><div className="panel-head"><h2>Change history</h2></div><div className="p-6 max-h-[500px] overflow-auto">{state.audit.map(a=><div className="timeline-item" key={a.id}><p className="text-sm">{a.action}</p><p className="text-xs muted mt-1">{timeText(a.at)} CT · {a.actor}</p></div>)}</div></section></>}
 <Dialog open={review} onOpenChange={setReview}><DialogContent><DialogHeader><DialogTitle>Review settings changes</DialogTitle><DialogDescription>These changes apply to future preparation and sending checks.</DialogDescription></DialogHeader><div className="callout">Sending window: {settings.start}–{settings.end} Central.<br/>Guest limit: {settings.weeklyLimit} proactive contacts per week.<br/><strong>{state.messages.filter(m=>m.status==='approved').length} approved messages will return to review.</strong><br/>Delivered messages and historical records are preserved.</div><DialogFooter><Button variant="outline" onClick={()=>setReview(false)}>Keep editing</Button><Button disabled={busy} onClick={async()=>{if(await run({type:'settings.save',settings})){dirty.current=false;setReview(false);}}}>Save settings</Button></DialogFooter></DialogContent></Dialog>
