 const [days,setDays]=useState(r?.days??0),[template,setTemplate]=useState(r?.template??''),[enabled,setEnabled]=useState(r?.enabled??true),[personId,setPersonId]=useState(modal.type==='compose'?modal.person?.id??'':'');
