 const title=modal.type==='person'?(p?'Edit person':'Add a person'):modal.type==='request'?(pr?'Review prayer request':'New prayer request'):modal.type==='message'?'Review message':modal.type==='rule'?'Edit follow-up rule':modal.type==='event'?(e?'Edit event':'Add event'):'Draft a personal message';
