 {modal.type==='message'&&m&&<><div className="flex gap-2 flex-wrap"><Badge tone={m.program==='prayer'?'teal':'blue'}>{m.program==='prayer'?'Prayer chain':'Guest follow-up'}</Badge><Badge>{m.channel.toUpperCase()}</Badge><Badge tone={m.status==='pending'?'amber':'gray'}>{m.status}</Badge><Badge>Revision {m.revision}</Badge></div>{editing?<><Field label="Subject / label"><Input value={subject} onChange={e=>setSubject(e.target.value)}/></Field><Field label="Exact message"><Textarea rows={7} value={body} onChange={e=>setBody(e.target.value)}/></Field><Field label={`Send no earlier than · ${localTimezone}`} note="Actual delivery will also respect Central sending hours."><Input type="datetime-local" value={schedule} onChange={e=>setSchedule(e.target.value)}/></Field><div className="soft-banner">Saving creates a new revision that needs approval.</div></>:<><h3>{m.subject}</h3>{m.prayerId&&<details><summary className="cursor-pointer text-teal-700">Original transcript</summary><p className="callout whitespace-pre-wrap mt-3">{state.prayers.find(p=>p.id===m.prayerId)?.original}</p></details>}<div className="callout !text-[15px] whitespace-pre-wrap">{m.body}</div><div className="flex gap-2 items-center text-sm muted"><Clock size={16}/>{timeText(m.scheduledAt)} CT · expires {m.program==='prayer'?'24':'48'} hours after approval{m.occurrence?' or when this repeat period ends, whichever is sooner':''}</div><div><h3 className="mb-3">Exact audience · {m.targets.length} {m.targets.length===1?'person':'people'}</h3><div className="border rounded-lg max-h-48 overflow-auto divide-y">{m.targets.map(t=>{const p=state.people.find(p=>p.id===t.personId),reason=eligible(state,m,t);return <div key={t.personId} className="p-3 text-sm flex justify-between gap-3"><span>{p?.name??'Removed person'}<span className="block text-xs muted">{t.destination}</span></span>{reason&&<span className="text-xs text-amber-700 max-w-44">Excluded: {reason}</span>}</div>;})}</div></div></>}<DialogFooter className="flex-wrap">{editing?<><Button variant="outline" onClick={()=>setEditing(false)}>Back to review</Button><Button disabled={busy||!body.trim()||!schedule} onClick={()=>save({type:'message.edit',id:m.id,revision:m.revision,body,subject,scheduledAt:new Date(schedule).toISOString()})}>Save new draft</Button></>:<><Button variant="outline" onClick={()=>setEditing(true)}><PenLine size={15}/>Edit</Button>{m.status!=='cancelled'&&<Button variant="ghost" disabled={busy} onClick={()=>save({type:'message.cancel',id:m.id})}>Dismiss draft</Button>}{m.status==='held'||m.status==='cancelled'?<Button disabled={busy} onClick={()=>save({type:'message.reopen',id:m.id})}>Refresh for review</Button>:<Button variant="outline" disabled={busy} onClick={()=>save({type:'message.hold',id:m.id})}><Pause size={15}/>Hold</Button>}{m.status==='pending'&&<Button disabled={busy||m.targets.every(t=>!!eligible(state,m,t))} onClick={()=>save({type:'message.approve',id:m.id,revision:m.revision})}><Check size={16}/>Approve exact message</Button>}</>}</DialogFooter></>}
